using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using AntColony.Units;using AntColony.Buildings;using AntColony.Core;
public static class Final1113BedChecks{
 public static async Task<string> Run(){var b=GameObject.Find("Final treatment beds").GetComponent<Infirmary>();var a=b.Patients.ToArray();if(a.Length!=2)throw new Exception("Need two patients");AntColony.UI.SimulationPause.UserSpeed(0);string report="";void Check(bool ok,string s){if(!ok)throw new Exception(s);report+="PASS "+s+"\n";}
 foreach(var c in a){Check(!c.Agent.updatePosition,"navigation held at bed "+c.CommanderName);Check(c.GetComponent<MeshyNativeMotionPlayer>().PlayingMotion=="Sleep_Normally","native sleep");b.TryRestPose(c,out var p,out _);Check(Vector2.Distance(new Vector2(c.Position.x,c.Position.z),new Vector2(p.x,p.z))<.01f,"identity at bed");}
 b.transform.rotation=Quaternion.Euler(0,90,0);await Task.Delay(200);foreach(var c in a){b.TryRestPose(c,out var p,out var direction);var model=c.GetComponent<MeshyNativeMotionPlayer>().NativeModel;var bones=model.GetComponentsInChildren<Transform>();var head=bones.First(t=>t.name=="mixamorig:Head");var feet=(bones.First(t=>t.name=="mixamorig:LeftFoot").position+bones.First(t=>t.name=="mixamorig:RightFoot").position)*.5f;Check(Vector3.Dot(Vector3.ProjectOnPlane(head.position-feet,Vector3.up).normalized,direction)>.99f,"rotated bed head direction");}
 b.Release(a[0]);Check(a[0].Agent.updatePosition&&a[0].Agent.isOnNavMesh,"release restores navigation");Check(a[0].TreatmentFacility==null&&!a[0].PersonalState.treating,"release clears treatment");var restore=typeof(Infirmary).GetMethod("RestorePatient",BindingFlags.Instance|BindingFlags.NonPublic);restore.Invoke(b,new object[]{a[0]});restore.Invoke(b,new object[]{a[0]});await Task.Delay(200);Check(b.Patients.Count==2,"restore duplicate protected");Check(a[0].GetComponent<MeshyNativeMotionPlayer>().PlayingMotion=="Sleep_Normally","paused restored patient lies");
 UnityEngine.Object.Destroy(b.gameObject);await Task.Delay(200);foreach(var c in a)Check(c.Agent.updatePosition&&c.TreatmentFacility==null,"destroy releases patient");File.WriteAllText("work/final-motion-1113/bed-checks.txt",report);return report;}
}
